import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"This Portfolio: One Design, Two Languages","description":"The meta-story: how this very site was specified, built on a custom VitePress design system, translated into two languages and shipped by an agent team.","frontmatter":{"title":"This Portfolio: One Design, Two Languages","description":"The meta-story: how this very site was specified, built on a custom VitePress design system, translated into two languages and shipped by an agent team."},"headers":[],"relativePath":"en/vibe-stories/story-4/index.md","filePath":"en/vibe-stories/story-4/index.md"}`),a={name:`en/vibe-stories/story-4/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="this-portfolio-one-design-two-languages" tabindex="-1">This Portfolio: One Design, Two Languages <a class="header-anchor" href="#this-portfolio-one-design-two-languages" aria-label="Permalink to “This Portfolio: One Design, Two Languages”">​</a></h1><p>You are looking at the most self-referential project in my portfolio: <strong>this website</strong>. It is a custom VitePress build — an Apple-style home, glass navigation, a typing tagline and a story carousel — implemented end to end with every text and image being my own content, in <strong>two languages</strong>: English and Spanish.</p><h2 id="why-this-design" tabindex="-1">Why this design? <a class="header-anchor" href="#why-this-design" aria-label="Permalink to “Why this design?”">​</a></h2><p>Because it is honest about what good engineering is: find something excellent, understand it completely, then adapt it with discipline. The Apple-style home, the glass chrome, the animated welcome, the MacBook-framed story carousel — all of it was studied, implemented and re-anchored to a current engine version, then filled with a life it was never written for.</p><h2 id="what-made-it-non-trivial" tabindex="-1">What made it non-trivial <a class="header-anchor" href="#what-made-it-non-trivial" aria-label="Permalink to “What made it non-trivial”">​</a></h2><ul><li><strong>A real i18n layer</strong> — the language switcher, per-locale routes and localized UI chrome (settings panel, slides, code toggles) all work end to end.</li><li><strong>Custom wordmark</strong> — the script &quot;Usf&quot; logo is generated from a real font into SVG paths so the animated welcome screen could keep its draw-on effect.</li><li><strong>Eighteen project covers and story illustrations</strong> — every card and story cover generated to match the theme&#39;s pastel aesthetic.</li><li><strong>Agent-team assembly</strong> — theme, content, translations and deployment ran as parallel agent workstreams, coordinated the <a href="/Usf/en/agentic/hermes/">Hermes way</a>.</li></ul><p>The source of truth lives at <a href="https://github.com/Godde3s/Usf" target="_blank" rel="noreferrer">github.com/Godde3s/Usf</a> — public, naturally. If you are reading this on the live site, the deploy pipeline worked; if you are reading it on GitHub, the pipeline is one <code>vitepress build</code> away.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};